import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const d="/assets/zh-cn_formulaimage_0000001957631821.CgmA0tJQ.png",R=JSON.parse('{"title":"Min","description":"","frontmatter":{},"headers":[{"level":1,"title":"Min","slug":"min"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/基础算术/Min-25.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/基础算术/Min-25.md"}'),l={name:"api/SIMD-API/基础API/Reg矢量计算/基础算术/Min-25.md"};function i(r,t,p,o,c,g){return e(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="min" tabindex="-1">Min <a class="header-anchor" href="#min" aria-label="Permalink to &quot;Min&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>根据mask对源操作数srcReg0、srcReg1进行按元素求最小值操作，将结果写入目的操作数dstReg。计算公式如下：</p><p><img src="'+d+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, MaskMergeMode mode = MaskMergeMode::ZEROING, typename U&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void Min(U&amp; dstReg, U&amp; srcReg0, U&amp; srcReg1, MaskReg&amp; mask)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t。</td></tr><tr><td>mode</td><td>选择MERGING模式或ZEROING模式。 ZEROING, mask未选中的元素在dstReg中置零。MERGING, mask未选择的元素对应dstReg元素中保留dstReg原值。</td></tr><tr><td>U</td><td>目的操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg0</td><td>输入</td><td>源操作数。 类型为RegTensor。 数据类型需要与目的操作数保持一致。</td></tr><tr><td>srcReg1</td><td>输入</td><td>源操作数。 类型为RegTensor。 数据类型需要与目的操作数保持一致。</td></tr><tr><td>mask</td><td>输入</td><td>源操作数元素操作的有效指示，详细说明请参考MaskReg。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>输入srcReg0为-0, srcReg1为+0的情况下，输出dstReg为-0。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void MinVF(__ubuf__ T* dstAddr, __ubuf__ T* src0Addr, __ubuf__ T* src1Addr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg1;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;    </span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg0, src0Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg1, src1Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>       </span></span>
<span class="line"><span>        AscendC::Reg::Min(dstReg, srcReg0, srcReg1, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,19)])])}const _=a(l,[["render",i]]);export{R as __pageData,_ as default};
